    touch(beat = {}) {
      lastBeatAt = Date.now();
      released = beat.alive === false;
      if (LANGUAGES.includes(beat.language)) language = beat.language;
      if (Array.isArray(beat.muted)) muted = normalizeMuted(beat.muted);
