      "content": "{\n  \"name\": \"dsh-notify-me\",\n  \"version\": \"1.19.0\",\n  \"description\": \"离开 DSH 页面也能收到提醒：需要你操作 / 后台回复完成时发系统通知、标题标记与提示音，支持审批快捷裁决与外部推送，Web 版与桌面版均可用。\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/page-bridge.js\",\n    \"lib/host-fallback.js\",\n    \"lib/relay.js\",\n    \"lib/focus-window.ps1\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\",\n    \"smoke/mac-notify-test.mjs\",\n    \"smoke/win-toast-test.mjs\",\n    \"macos/DSHNotify.swift\",\n    \"macos/build.sh\",\n    \"lib/mac-notify.js\",\n    \"lib/win-toast.js\",\n    \"lib/win-toast.ps1\"\n  ],\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"dsh-web\",\n    \"notification\",\n    \"desktop-notification\",\n    \"notify\",\n    \"notifications\",\n    \"alerts\",\n    \"reminder\",\n    \"reminders\",\n    \"message-alert\",\n    \"needs-your-input\",\n    \"approval-alert\",\n    \"approval-actions\",\n    \"idle-detection\",\n    \"auto-dismiss\",\n    \"background-alert\",\n    \"external-notification\",\n    \"webhook\",\n    \"discord\",\n    \"bark\",\n    \"gotify\",\n    \"feishu\",\n    \"serverchan\",\n    \"wxpusher\",\n    \"push-notification\",\n    \"桌面通知\",\n    \"消息提醒\",\n    \"可操作提醒\",\n    \"审批提醒\",\n    \"提醒插件\",\n    \"需要你操作\",\n    \"回复完成提醒\",\n    \"后台完成提醒\",\n    \"外部通知\",\n    \"推送提醒\",\n    \"提醒\",\n    \"闲置判定\",\n    \"离开判定\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node smoke/smoke-test.cjs && node smoke/host-route-test.mjs && node smoke/page-bridge-test.mjs && node smoke/host-fallback-test.mjs && node smoke/relay-route-test.mjs && node smoke/cordis-host-test.mjs && node smoke/mac-notify-test.mjs && node smoke/win-toast-test.mjs\",\n    \"pack\": \"npm pack --dry-run\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"author\": \"chromoany\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/chromoany/dsh-notify-me.git\"\n  },\n  \"homepage\": \"https://github.com/chromoany/dsh-notify-me#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/chromoany/dsh-notify-me/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-session\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.1.1-rc.2\": \"compatible\",\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.5-rc.2\": \"compatible\",\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.1-rc.4\": \"compatible\",\n        \"0.2.1-rc.5\": \"compatible\",\n        \"0.2.2-alpha.2\": \"compatible\",\n        \"0.2.2-rc.1\": \"compatible\"\n      }\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-client-locale\": \"^0.1.0-rc.6 || ^0.1.1-rc.2 || ^0.1.2-rc.1 || ^0.1.5-rc.1 || >=0.1.6-alpha.2 <0.2.0-0 || >=0.2.0-rc.1 <0.3.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    }\n  }\n}\n"
